#[derive(Clone, Debug, Eq, PartialEq)]
pub struct URL {
    scheme: String,
    host: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
    valid: bool,
}

impl URL {
    pub fn from_components(
        scheme: &str,
        host: &str,
        port: i32,
        path: &str,
        query: &str,
        fragment: &str,
    ) -> Self {
        let normalized_path = if path.is_empty() || path.starts_with('/') {
            path.to_owned()
        } else {
            format!("/{path}")
        };

        Self {
            scheme: scheme.to_ascii_lowercase(),
            host: host.to_owned(),
            port: if (0..=65535).contains(&port) {
                port
            } else {
                -1
            },
            path: normalized_path,
            query: query.to_owned(),
            fragment: fragment.to_owned(),
            valid: !host.is_empty() || !path.is_empty(),
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn to_string(&self) -> String {
        let mut result = String::new();

        if !self.scheme.is_empty() {
            result.push_str(&self.scheme);
            result.push_str("://");
            result.push_str(&self.host);

            if self.port >= 0 {
                result.push(':');
                result.push_str(&self.port.to_string());
            }
        }

        result.push_str(&self.path);

        if !self.query.is_empty() {
            result.push('?');
            result.push_str(&self.query);
        }

        if !self.fragment.is_empty() {
            result.push('#');
            result.push_str(&self.fragment);
        }

        result
    }

    pub fn is_valid(&self) -> bool {
        self.valid
    }
}

