fn terminate_stoi(kind: &str) -> ! {
    eprintln!("terminate called after throwing an instance of 'std::{kind}'");
    eprintln!("  what():  stoi");
    process::abort();
}

fn parse_stoi(value: &str) -> i32 {
    let bytes = value.as_bytes();
    let mut index = 0;

    while index < bytes.len() && matches!(bytes[index], b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c) {
        index += 1;
    }

    let negative = if index < bytes.len() && (bytes[index] == b'+' || bytes[index] == b'-') {
        let is_negative = bytes[index] == b'-';
        index += 1;
        is_negative
    } else {
        false
    };

    if index == bytes.len() || !bytes[index].is_ascii_digit() {
        terminate_stoi("invalid_argument");
    }

    let limit = if negative { 2_147_483_648_i64 } else { 2_147_483_647_i64 };
    let mut parsed = 0_i64;

    while index < bytes.len() && bytes[index].is_ascii_digit() {
        let digit = i64::from(bytes[index] - b'0');
        if parsed > (limit - digit) / 10 {
            terminate_stoi("out_of_range");
        }
        parsed = parsed * 10 + digit;
        index += 1;
    }

    if negative {
        -(parsed as i32)
    } else {
        parsed as i32
    }
}

