// std::stoi equivalent (base 10, no full-consumption check)
fn stoi(s: &str) -> Result<i32, StoiErr> {
    let b = s.as_bytes();
    let mut i = 0;
    while i < b.len() && matches!(b[i], b' '|b'\t'|b'\n'|b'\x0b'|b'\x0c'|b'\r') { i += 1; }
    let neg = match b.get(i) { Some(b'+') => {i+=1; false}, Some(b'-') => {i+=1; true}, _ => false };
    let start = i;
    let mut v: i64 = 0; // strtol accumulates as i64 (long), clamps to i64::MIN/MAX with ERANGE
    let mut erange = false;
    while i < b.len() && b[i].is_ascii_digit() {
        v = v*10 + (b[i]-b'0') as i64;             // on i64 overflow: clamp to i64::MAX (or MIN if neg), erange = true
        i += 1;
    }
    if i == start { return Err(StoiErr::InvalidArgument); }   // no digits (incl. empty, ws-only, bare sign)
    if neg { v = -v; }
    if erange || v < i32::MIN as i64 || v > i32::MAX as i64 { return Err(StoiErr::OutOfRange); }
    Ok(v as i32)                                    // trailing junk ignored
}
// On Err: eprintln "terminate called after throwing an instance of
// 'std::invalid_argument'|'std::out_of_range'\n  what():  stoi"; abort via SIGABRT (exit 134).

// from_components / set_port normalization
let port: i32 = if (0..=65535).contains(&p) { p } else { -1 };
let is_valid = !host.is_empty() || !path.is_empty();

// to_string
